        float angle=(amzp_rotation+amzp_rotationRandom*rnd.x+amzp_rotationSpeed*(1.0+amzp_spinRandom*rnd.y)*age)*0.01745329252;
        float2 direction=motion.xy*p.z-p.xy*motion.z;
        if((amzp_alignVelocity>0.5)&&dot(direction,direction)>0.000001)angle+=atan(direction.y,direction.x);
        float2 offset=(amzLocal_screen-center)/(2.0*amzLocal_size);
        float ca=cos(angle),sa=sin(angle);
        float2 uv=float2(ca*offset.x+sa*offset.y,-sa*offset.x+ca*offset.y)+0.5;
        if (uv.x<0.0||uv.x>1.0||uv.y<0.0||uv.y>1.0) continue;
        float fade=mix(amzp_opacityStart,amzp_opacityEnd,lifeMix)*(1.0-amzp_opacityRandom*labHash(fi,cycle,233.0));
        if((amzp_softFade>0.5))fade*=smoothstep(0.0,0.08,u)*(1.0-smoothstep(0.65,1.0,u));
        float4 particle;
        if ((amzp_useTexture>0.5)) {
          particle=amzTexture(0,(float4(uv,0.0,1.0)*amzLayerToScreen()).xy);
        } else {
          float a=1.0-smoothstep(0.25,0.5,length(uv-0.5));
          particle=float4(a);
        }
        float4 color=amzp_tint*mix(amzp_colorStart,amzp_colorEnd,lifeMix);
        color.rgb*=mix(float3(1.0),(rnd+1.0)*0.5,amzp_colorRandom);
        particle*=float4(color.rgb,1.0)*color.a*fade;
        if ((amzp_additive>0.5)) result+=particle;
        else result=particle+result*(1.0-particle.a);
      }
      amzOutput=clamp(result,0.0,1.0);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
